SELECT [AB PLS EVB].[Enddatum der Messung], [AB PLS EVB].[Zeit Ende], [AB PLS EVB]![kWh/t NaOH]-7*(90-([PLS]![Mittlere Katholyttemperatur]+[PLS]![Mittlere Anolyttemperatur])/2)-6*([PLS]![Produktion]*[PLS]![Mittlere NaOH Konzentration]*0.01/[AB PLS Produktion]![h]*24-[PLS]![Garantierte Produktion])/[PLS]![Garantierte Produktion]*100-14*([PLS]![Mittlere NaOH Konzentration]-32) AS EK
FROM ([AB PLS EVB] INNER JOIN [AB PLS Produktion] ON ([AB PLS EVB].[Zeit Ende] = [AB PLS Produktion].[Zeit Ende]) AND ([AB PLS EVB].[Enddatum der Messung] = [AB PLS Produktion].[Enddatum der Messung])) INNER JOIN PLS ON ([AB PLS Produktion].[Zeit Ende] = PLS.[Zeit Ende]) AND ([AB PLS Produktion].[Enddatum der Messung] = PLS.[Enddatum der Messung]);
